class Solution {
public:
    long long maximumTotalDamage(vector<int>& power) {
        sort(power.begin(), power.end());
        int n = power.size();
        vector<long long> vals, cnt;
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && power[j] == power[i]) j++;
            vals.push_back(power[i]);
            cnt.push_back(j - i);
            i = j;
        }
        int m = vals.size();
        vector<long long> dp(m + 1, 0);
        int ptr = 0;
        for (int i = 0; i < m; i++) {
            while (ptr < i && vals[ptr] <= vals[i] - 3) ptr++;
            long long take = cnt[i] * vals[i] + dp[ptr];
            dp[i + 1] = max(dp[i], take);
        }
        return dp[m];
    }
};
